// Verify Quo/OpenPhone HMAC signature
const crypto = require('crypto');

const signature = $input.first().headers['openphone-signature'];
const payload = JSON.stringify($input.first().body);
const secret = $env.QUO_WEBHOOK_SIGNING_SECRET_BASE64;

if (!signature || !secret) {
  throw new Error('Missing signature or secret');
}

// Parse signature: hmac;1;<timestamp>;<base64_digest>
const parts = signature.split(';');
if (parts.length !== 4 || parts[0] !== 'hmac' || parts[1] !== '1') {
  throw new Error('Invalid signature format');
}

const timestamp = parts[2];
const receivedDigest = parts[3];

// Check timestamp (30 minute tolerance)
const timestampMs = parseInt(timestamp);
const now = Date.now();
if (Math.abs(now - timestampMs) > 30 * 60 * 1000) {
  throw new Error('Timestamp too old');
}

// Compute expected digest
const signedData = timestamp + '.' + payload;
const keyBuffer = Buffer.from(secret, 'base64');
const expectedDigest = crypto
  .createHmac('sha256', keyBuffer)
  .update(signedData)
  .digest('base64');

if (receivedDigest !== expectedDigest) {
  throw new Error('Signature mismatch');
}

// Return verified payload
return [{
  json: {
    verified: true,
    event: $input.first().body,
    timestamp: timestamp
  }
}];

// Extract or create comm_thread for message
const event = $('Verify HMAC Signature').item.json.event;
const data = event.data;

const contactPhone = data.direction === 'incoming' 
  ? data.from 
  : data.to[0];

return [{
  json: {
    contact_phone: contactPhone,
    external_phone_number_id: data.phoneNumberId,
    direction: data.direction === 'incoming' ? 'inbound' : 'outbound',
    message: {
      external_message_id: data.id,
      from_phone: data.from,
      to_phone: data.to[0],
      body: data.body,
      media: data.media || [],
      status: data.status,
      sent_at: data.createdAt,
      received_at: data.direction === 'incoming' ? data.createdAt : null
    },
    raw_event: event
  }
}];

// Extract call data
const event = $('Verify HMAC Signature').item.json.event;
const data = event.data;

const contactPhone = data.direction === 'incoming' 
  ? data.from 
  : data.to;

return [{
  json: {
    contact_phone: contactPhone,
    external_phone_number_id: data.phoneNumberId,
    direction: data.direction === 'incoming' ? 'inbound' : 'outbound',
    call: {
      external_call_id: data.id,
      from_phone: data.from,
      to_phone: data.to,
      started_at: data.createdAt,
      ended_at: data.completedAt,
      answered_at: data.answeredAt,
      duration_seconds: data.duration,
      recording_url: data.recording?.url || null
    },
    raw_event: event
  }
}];

// Update call with transcript
const event = $('Verify HMAC Signature').item.json.event;
const data = event.data;

return [{
  json: {
    external_call_id: data.callId,
    transcript: data.transcript,
    summary: data.summary || null,
    action_items: data.actionItems || []
  }
}];

