// Parse LLM response and create action queue items
const extraction = JSON.parse($json.content[0].text);
const sourceData = $('Process Message').item?.json || $('Process Transcript').item?.json;

const actions = [];

// Create action based on intent
if (extraction.next_step === 'create_job' || extraction.intent === 'schedule') {
  actions.push({
    source_type: sourceData.message ? 'message' : 'call',
    source_id: sourceData.message?.external_message_id || sourceData.external_call_id,
    kind: 'create_job',
    payload: {
      title: `Service Request - ${extraction.issue?.service_type || 'General'}`,
      customer: extraction.customer,
      location: extraction.location,
      service_type: extraction.issue?.service_type,
      problem_description: extraction.issue?.problem_description,
      scheduled_start: extraction.time?.preferred_start,
      scheduled_end: extraction.time?.preferred_end,
      time_confidence: extraction.time?.confidence
    },
    requires_approval: true,
    status: 'pending'
  });
}

if (extraction.intent === 'schedule' && extraction.time?.confidence >= 0.85) {
  actions.push({
    source_type: sourceData.message ? 'message' : 'call',
    source_id: sourceData.message?.external_message_id || sourceData.external_call_id,
    kind: 'schedule_job',
    payload: {
      scheduled_start: extraction.time.preferred_start,
      scheduled_end: extraction.time.preferred_end,
      customer: extraction.customer,
      location: extraction.location
    },
    requires_approval: true,
    status: 'pending'
  });
}

if (extraction.intent === 'quote' || extraction.next_step === 'create_estimate') {
  actions.push({
    source_type: sourceData.message ? 'message' : 'call',
    source_id: sourceData.message?.external_message_id || sourceData.external_call_id,
    kind: 'create_estimate',
    payload: {
      service_type: extraction.issue?.service_type,
      problem_description: extraction.issue?.problem_description,
      customer: extraction.customer,
      location: extraction.location
    },
    requires_approval: true,
    status: 'pending'
  });
}

return actions.map(action => ({ json: { ...action, ai_extraction: extraction } }));
